import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as byteStr from "./byte_str.ts";
import * as panic from "./panic.ts";
import * as ial from "./ial.ts";
import * as rune from "./rune.ts";
import * as url from "./url.ts";
import * as conv from "../runtime/conv.ts";

// Vectors are generated by ts/tools/gen-util-vectors from Go's real util package
// (-tags javascript). Byte inputs are lowercase hex (argsHex). A string result
// (ret) is the Go string where each invalid byte became U+FFFD, which is what the
// TypeScript port returns; retHex is the exact bytes, and retValid says whether
// they are valid UTF-8. Errors are err plus errMsg, the Go Error() text. A Go
// panic is "panic": true, and the TypeScript call must throw.

interface GoCase {
  args?: unknown[];
  argsHex?: string[];
  ret?: unknown;
  retHex: string;
  retValid: boolean;
  err: boolean;
  errMsg?: string;
  panic: boolean;
}

interface Vectors {
  goVersion: string;
  functions: Record<string, GoCase[]>;
}

const vectors: Vectors = JSON.parse(readFileSync(new URL("./testdata/util_vectors.json", import.meta.url), "utf8"));

// fromHex decodes hex into a fresh array whose capacity equals its length.
const fromHex = (s: string): Uint8Array => new Uint8Array(Buffer.from(s, "hex"));

// hx encodes bytes as lowercase hex.
const hx = (u: Uint8Array): string => Buffer.from(u).toString("hex");

// each runs body on every vector of name. A vector with a Go panic must make body
// throw. The count is checked against the 80 inputs the generator must produce.
function each(name: string, body: (c: GoCase, where: string) => void): void {
  const cs: GoCase[] = vectors.functions[name] ?? [];
  test(`${name} matches Go (${cs.length} vectors)`, () => {
    assert.ok(cs.length >= 80, `${name}: expected at least 80 vectors, got ${cs.length}`);
    cs.forEach((c, i) => {
      const where = `${name}#${i} args=${JSON.stringify(c.args ?? c.argsHex)}`;
      if (c.panic) {
        assert.throws(() => body(c, where), where);
        return;
      }
      body(c, where);
    });
  });
}

test("every exported function of the ported files has vectors", () => {
  assert.deepEqual(Object.keys(vectors.functions).sort(), [
    "BytesToStr",
    "ContainsStr",
    "EscapeError",
    "InvalidHostError",
    "IsDigit",
    "IsDocIAL",
    "IsDocIAL2",
    "IsEmptyStr",
    "PathEscape",
    "PathUnescape",
    "RecoverPanic",
    "StrToBytes",
    "WordCount",
  ]);
});

each("StrToBytes", (c, where) => {
  const got = byteStr.StrToBytes(c.args![0] as string);
  assert.equal(hx(got), c.retHex, where);
  assert.equal(c.retValid, true, where);
});

each("BytesToStr", (c, where) => {
  const got = byteStr.BytesToStr(fromHex(c.argsHex![0]!));
  assert.equal(got, c.ret, where);
});

each("IsDocIAL", (c, where) => {
  assert.equal(ial.IsDocIAL(fromHex(c.argsHex![0]!)), c.ret, where);
});

each("IsDocIAL2", (c, where) => {
  assert.equal(ial.IsDocIAL2(c.args![0] as string[][]), c.ret, where);
});

each("ContainsStr", (c, where) => {
  assert.equal(rune.ContainsStr(c.args![0] as string, c.args![1] as string[]), c.ret, where);
});

each("IsEmptyStr", (c, where) => {
  assert.equal(rune.IsEmptyStr(c.args![0] as string), c.ret, where);
});

each("IsDigit", (c, where) => {
  assert.equal(rune.IsDigit(c.args![0] as string), c.ret, where);
});

each("WordCount", (c, where) => {
  assert.deepEqual(rune.WordCount(c.args![0] as string), c.ret, where);
});

each("PathEscape", (c, where) => {
  assert.equal(url.PathEscape(c.args![0] as string), c.ret, where);
});

each("PathUnescape", (c, where) => {
  const [got, err] = url.PathUnescape(c.args![0] as string);
  assert.equal(got, c.ret, where);
  assert.equal(err !== null, c.err, where);
  if (err !== null) {
    assert.equal(err.message, c.errMsg, where);
  }
});

each("EscapeError", (c, where) => {
  assert.equal(new url.EscapeError(conv.BytesFromString(c.args![0] as string)).message, c.ret, where);
});

each("InvalidHostError", (c, where) => {
  assert.equal(new url.InvalidHostError(conv.BytesFromString(c.args![0] as string)).message, c.ret, where);
});

each("RecoverPanic", (c) => {
  // Go's argument is a *error: nil for null, otherwise a non-nil error.
  const a = c.args![0];
  panic.RecoverPanic(typeof a === "string" ? new Error(a) : null);
});
